package com.codepilot1c.core.edt.debug;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import com.google.gson.*;import com.codepilot1c.core.edt.development.*;import com.codepilot1c.core.edt.infobase.*;import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
/** One durable launch request and explicit decision; observing never dispatches another launch. */
public final class DebugLaunchRequests {
 public interface Backend{Map<String,Object> binding(String project)throws Exception;void update(String project)throws Exception;Map<String,Object> launch(String project,String config,boolean updateAuthorized)throws Exception;}
 private static final Object LOCK=new Object();private static final Set<String> ACTIVE=java.util.concurrent.ConcurrentHashMap.newKeySet();private static final Gson JSON=new GsonBuilder().serializeNulls().create();private final Path root;private final Backend backend;
 public DebugLaunchRequests(Path root,Backend b)throws Exception{this.root=root.toAbsolutePath().normalize();backend=b;Files.createDirectories(this.root);checkRoot();}
 private void checkRoot()throws Exception{if(!root.toRealPath().equals(root)||Files.isSymbolicLink(root))throw new IllegalStateException("Launch storage moved");}
 public static DebugLaunchRequests workspace()throws Exception{return new DebugLaunchRequests(org.eclipse.core.resources.ResourcesPlugin.getWorkspace().getRoot().getLocation().toFile().toPath().resolve(".metadata/.plugins/com.codepilot1c.core/debug-launch-requests"),new Backend(){public Map<String,Object> binding(String p)throws Exception{return new RuntimePreparationBackend().binding(p);}public void update(String p)throws Exception{new NativeInfobaseGateway().updateIncremental(p,new org.eclipse.core.runtime.NullProgressMonitor());}public Map<String,Object> launch(String p,String config,boolean authorized)throws Exception{var runtime=new com.codepilot1c.core.edt.runtime.EdtRuntimeService();var base=runtime.resolveDefaultInfobase(p);try(var interaction=NativeUpdateInteraction.observeLaunch(p,base,authorized)){return EdtDebugService.getInstance().launchDebugSession(p,config,false);}}});}
 private Path file(String id)throws Exception{checkRoot();if(id==null||!id.matches("dbg-launch-[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid debug_launch_id");Path f=root.resolve(id+".json");if(Files.isSymbolicLink(f))throw new IllegalStateException("Linked launch receipt");return f;}
 private void save(Map<String,Object>d)throws Exception{Path f=file((String)d.get("debug_launch_id")),t=Files.createTempFile(root,"launch-",".tmp");try{String data=JSON.toJson(d);if(data.length()>128*1024)throw new IllegalStateException("Launch receipt capacity");Files.writeString(t,data,StandardCharsets.UTF_8);Files.move(t,f,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(t);}}
 @SuppressWarnings("unchecked") private Map<String,Object> read(String id)throws Exception{Path f=file(id);if(!Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS)||Files.size(f)>128*1024)throw new IllegalStateException("Launch receipt unavailable");var d=JSON.fromJson(Files.readString(f),LinkedHashMap.class);if(!id.equals(d.get("debug_launch_id")))throw new IllegalStateException("Launch identity changed");return d;}
 private String activeKey(String id){return root+":"+id;}
 private static Map<String,Object> identity(Map<String,Object>b){var c=new LinkedHashMap<>(b);c.remove("configuration_synchronized");return c;}
 private Map<String,Object> decision(Map<String,Object>d){var scope=new LinkedHashMap<String,Object>();for(String k:List.of("debug_launch_id","project","configuration_name","binding"))scope.put(k,d.get(k));String hash=TaskSessionService.fingerprint(scope);var choices=new ArrayList<Map<String,Object>>();for(String choice:List.of("update_and_launch","cancel"))choices.add(Map.of("id",choice,"label",choice.equals("update_and_launch")?"Обновить и запустить":"Отменить","updates_database",choice.equals("update_and_launch"),"command",Map.of("tool","edt.debug","arguments",Map.of("op","edt_debug_targets","args",Map.of("action","launch_decide","debug_launch_id",d.get("debug_launch_id"),"expected_decision_sha256",hash,"choice",choice)))));return Map.of("kind","update_before_debug","decision_id",d.get("debug_launch_id"),"decision_sha256",hash,"project",d.get("project"),"base_uuid",TaskSessionService.object(d.get("binding")).get("base_uuid"),"choices",choices,"default_policy","ask_user_unless_task_explicitly_authorizes_database_update");}
 public Map<String,Object> start(String project,String config,String key,String policy)throws Exception{synchronized(LOCK){if(project==null||project.isBlank()||config==null||config.isBlank()||key==null||key.isBlank()||key.length()>256||!Set.of("ask","task_authorized_update").contains(policy))throw new IllegalArgumentException("Explicit project/configuration/key and known decision_policy required");String id="dbg-launch-"+TaskSessionService.fingerprint(List.of(project,key));var request=Map.of("project",project,"configuration_name",config,"idempotency_key",key,"decision_policy",policy);String digest=TaskSessionService.fingerprint(request);if(Files.exists(file(id))){var old=read(id);if(!digest.equals(old.get("request_sha256")))throw new IllegalStateException("Launch key arguments changed");return status(id);}try(var paths=Files.list(root)){var files=paths.filter(f->f.getFileName().toString().matches("dbg-launch-[a-f0-9]{64}[.]json")).limit(129).toList();if(files.size()>128)throw new IllegalStateException("Archive reviewed launch receipts first");for(Path f:files){var old=read(f.getFileName().toString().replace(".json",""));if(project.equals(old.get("project"))&&Set.of("queued","running","outcome_unknown","awaiting_decision").contains(old.get("state")))throw new IllegalStateException("Inspect original launch request: "+old.get("debug_launch_id"));}}var binding=backend.binding(project);if(!(binding.get("base_uuid") instanceof String baseUuid)||baseUuid.isBlank())throw new IllegalStateException("Exact bound base required");var d=new LinkedHashMap<String,Object>(request);d.put("debug_launch_id",id);d.put("request_sha256",digest);d.put("binding",binding);d.put("state","awaiting_decision");save(d);if(Boolean.TRUE.equals(binding.get("configuration_synchronized"))||policy.equals("task_authorized_update"))queue(d,policy.equals("task_authorized_update"));return status(id);}}
 private void queue(Map<String,Object>d,boolean allowUpdate)throws Exception{String id=(String)d.get("debug_launch_id");d.put("state","queued");d.put("update_authorized",allowUpdate);save(d);var gate=new java.util.concurrent.CountDownLatch(1);var armed=new java.util.concurrent.atomic.AtomicBoolean();ACTIVE.add(activeKey(id));try{String job=BackgroundJobRegistry.getInstance().startJob("debug-launch",()->{gate.await();if(!armed.get())throw new IllegalStateException("Launch reservation not persisted");try{return JSON.toJson(execute(id));}finally{ACTIVE.remove(activeKey(id));}});d.put("job_id",job);save(d);armed.set(true);}finally{gate.countDown();if(!armed.get())ACTIVE.remove(activeKey(id));}}
 private Map<String,Object> execute(String id)throws Exception{Map<String,Object>d; synchronized(LOCK){d=read(id);d.put("state","running");save(d);}boolean launchClaimed=false,updateClaimed=false;try{String p=(String)d.get("project");var current=backend.binding(p);if(!TaskSessionService.fingerprint(identity(current)).equals(TaskSessionService.fingerprint(identity(TaskSessionService.object(d.get("binding"))))))throw new IllegalStateException("Launch binding changed");if(!Boolean.TRUE.equals(current.get("configuration_synchronized"))){if(!Boolean.TRUE.equals(d.get("update_authorized")))throw new IllegalStateException("Native EQUAL required; no update authorized");updateClaimed=true;backend.update(p);current=backend.binding(p);if(!Boolean.TRUE.equals(current.get("configuration_synchronized")))throw new IllegalStateException("Update did not prove EQUAL");}if(!TaskSessionService.fingerprint(identity(current)).equals(TaskSessionService.fingerprint(identity(TaskSessionService.object(d.get("binding"))))))throw new IllegalStateException("Launch binding changed");launchClaimed=true;d.put("result",backend.launch(p,(String)d.get("configuration_name"),Boolean.TRUE.equals(d.get("update_authorized"))));d.put("state",Boolean.TRUE.equals(backend.binding(p).get("configuration_synchronized"))?"launched":"launched_unverified");}catch(Exception e){d.put("state",launchClaimed||updateClaimed?"outcome_unknown":"blocked");d.put("error_type",e.getClass().getSimpleName());}synchronized(LOCK){save(d);return status(id);}}
 public Map<String,Object> status(String id)throws Exception{synchronized(LOCK){var d=read(id);if(Set.of("queued","running").contains(d.get("state"))&&!ACTIVE.contains(activeKey(id))){d.put("state","outcome_unknown");d.put("reason","interrupted_or_unclaimed_no_replay");}d.put("terminal",!Set.of("queued","running","awaiting_decision").contains(d.get("state")));d.put("automatic_replay",false);d.put("test_acceptance_verified",false);if(ACTIVE.contains(activeKey(id))&&d.get("job_id") instanceof String job)d.put("progress",BackgroundJobRegistry.getInstance().getProgress(job));if("awaiting_decision".equals(d.get("state")))d.put("decision",decision(d));return d;}}
 public Map<String,Object> decide(String id,String expected,String choice)throws Exception{synchronized(LOCK){var d=read(id);if(!"awaiting_decision".equals(d.get("state"))||!Objects.equals(expected,decision(d).get("decision_sha256")))throw new IllegalStateException("STALE_LAUNCH_DECISION");if(!Set.of("cancel","update_and_launch").contains(choice))throw new IllegalArgumentException("Unknown launch decision");if(choice.equals("cancel")){d.put("state","cancelled");save(d);}else{var current=backend.binding((String)d.get("project"));if(!TaskSessionService.fingerprint(identity(current)).equals(TaskSessionService.fingerprint(identity(TaskSessionService.object(d.get("binding"))))))throw new IllegalStateException("Decision binding changed");queue(d,true);}return status(id);}}
}
